import hashlib

index = {}      # chunk_id -> {"doc": doc_id, "text": ...}
doc_hash = {}   # doc_id -> content hash from the last sync

def chunk(text, size=40):
    return [text[i:i + size] for i in range(0, len(text), size)]

def upsert_doc(doc_id, text):
    h = hashlib.sha256(text.encode()).hexdigest()
    if doc_hash.get(doc_id) == h:
        return "unchanged"                       # skip re-embedding
    delete_doc(doc_id)                           # drop ALL old chunks first
    for n, piece in enumerate(chunk(text)):
        index[f"{doc_id}#{n}"] = {"doc": doc_id, "text": piece}   # embed here
    doc_hash[doc_id] = h
    return "indexed"

def delete_doc(doc_id):
    for cid in [c for c, v in index.items() if v["doc"] == doc_id]:
        del index[cid]
    doc_hash.pop(doc_id, None)

def reconcile(source_ids):
    # Nightly safety net: remove anything the source no longer has.
    for doc_id in set(doc_hash) - set(source_ids):
        delete_doc(doc_id)

print(upsert_doc("policy-4", "Returns accepted within 30 days with receipt. Store credit after that."))
print(upsert_doc("policy-4", "Returns accepted within 14 days with receipt."))  # shorter: fewer chunks
print(sorted(index))            # ['policy-4#0', 'policy-4#1'] and no stale #2
reconcile(source_ids=[])        # doc deleted at the source
print(index)                    # {}

# A rough screen, not a formula. Each signal scores 0 (no), 1 (partly), 2 (yes).
SIGNALS = {
    "value_needs_custom_integration": "Value appears only after wiring into customer systems",
    "large_contracts": "Deals are large enough to fund engineers per customer",
    "messy_customer_data": "Customer data is scattered, dirty or locked down",
    "customer_lacks_capacity": "Customer teams cannot build the last mile themselves",
    "product_still_forming": "Field learnings still change the core product",
    "high_stakes_domain": "Errors are costly (health, finance, defence, safety)",
}

def fde_fit(scores):
    total = sum(scores.values())
    top = 2 * len(SIGNALS)
    if total >= 0.7 * top:
        verdict = "strong case for FDEs"
    elif total >= 0.4 * top:
        verdict = "FDEs for the largest accounts only; keep a self-serve path"
    else:
        verdict = "invest in docs, product and support engineers instead"
    return total, top, verdict

vertical_ai_startup = {"value_needs_custom_integration": 2, "large_contracts": 2,
                       "messy_customer_data": 2, "customer_lacks_capacity": 1,
                       "product_still_forming": 2, "high_stakes_domain": 1}
print(fde_fit(vertical_ai_startup))   # (10, 12, 'strong case for FDEs')

# Compare today's incoming schema with the agreed contract.
contract = {"order_id": "int", "customer_id": "int", "amount": "float",
            "currency": "str", "created_at": "timestamp"}
incoming = {"order_id": "int", "customer_id": "str", "amount_gross": "float",
            "currency": "str", "created_at": "timestamp", "channel": "str"}

def detect_drift(contract, incoming):
    added = sorted(set(incoming) - set(contract))
    removed = sorted(set(contract) - set(incoming))
    retyped = sorted(c for c in set(contract) & set(incoming)
                     if contract[c] != incoming[c])
    return {"added": added, "removed": removed, "retyped": retyped}

def decide(drift):
    if drift["removed"] or drift["retyped"]:
        return "FAIL: quarantine the batch, alert the owner, keep yesterday's tables"
    if drift["added"]:
        return "WARN: load known columns, log new ones for review"
    return "OK"

d = detect_drift(contract, incoming)
print(d)   # added: amount_gross, channel; removed: amount; retyped: customer_id
print(decide(d))

# Three-point (PERT) estimate per task, in engineer-days
tasks = {
    "SSO login (customer IdP)":        (1, 2, 6),    # (best, likely, worst)
    "Ingest 3 SharePoint sites":       (3, 5, 12),
    "Eval set + judge (60 cases)":     (2, 3, 5),
    "Deploy to customer Kubernetes":   (2, 4, 10),
}

def pert(o, m, p):
    return (o + 4 * m + p) / 6, (p - o) / 6       # expected, rough std dev

def tshirt(days):
    for size, limit in (("XS", 1), ("S", 3), ("M", 5), ("L", 10)):
        if days <= limit:
            return size
    return "XL: split it"

total = 0
for name, (o, m, p) in tasks.items():
    exp, sd = pert(o, m, p)
    total += exp
    print(f"{name:32} {exp:5.1f} d  +/-{sd:.1f}  {tshirt(exp)}")
print(f"{'Total':32} {total:5.1f} d")
